function systemSVG(selected='match'){
 let near=new Set([selected,...edges.filter(e=>e.includes(selected)).flat()]);
 const paths=edges.map(([a,b])=>{let u=C[a],v=C[b],x1=u.x+110,y1=u.y+68,x2=v.x+110,y2=v.y;if(v.x>u.x){x1=u.x+220;y1=u.y+34;x2=v.x;y2=v.y+34;}else if(v.x<u.x){x1=u.x;y1=u.y+34;x2=v.x+220;y2=v.y+34;}else if(v.y<u.y){x1=u.x+225;y1=u.y+34;x2=v.x+225;y2=v.y+34;}const mid=(x1+x2)/2;let d=`M${x1},${y1} C${mid},${y1} ${mid},${y2} ${x2},${y2}`;if(a==='verify'&&b==='inventory')d=`M${u.x},${u.y+20} C280,540 280,220 ${v.x},${v.y+40}`;return `<path class="flow-edge ${a===selected||b===selected?'lit':''} ${a==='assistant'?'draft-edge':''}" d="${d}" marker-end="url(#arrow)"/>`;}).join('');
 return `<svg viewBox="0 0 890 665" role="img" aria-labelledby="map-title map-desc"><title id="map-title">Proposed system map</title><desc id="map-desc">Source knowledge and asset observations meet at applicability. Priority precedes approval, execution and independent verification. Select a component to inspect its tasks and evidence.</desc><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M0 0L10 5L0 10Z" fill="#91a7ba"/></marker></defs><rect x="612" y="544" width="246" height="100" rx="14" fill="#fff4df" stroke="#d1a653" stroke-dasharray="5 4"/><text x="735" y="657" class="boundary-label">PRIVILEGED RUNNER BOUNDARY</text>${paths}${components.map(c=>`<a href="#system/${c.id}" aria-label="${esc(c.label+' — '+c.owner)}" ${c.id===selected?'aria-current="true"':''}><g class="map-node ${c.id===selected?'selected':''} ${near.has(c.id)?'near':'dim'}" style="--node:${color[c.stream]}"><rect x="${c.x}" y="${c.y}" width="220" height="68" rx="12"/><text class="node-title" x="${c.x+110}" y="${c.y+27}">${esc(c.label)}</text><text class="node-sub" x="${c.x+110}" y="${c.y+49}">${esc(c.sub)}</text></g></a>`).join('')}</svg>`;
}

const decisionCopy=[["Intelligence backbone", "CVEListV5 + vendor assertions + asynchronous NVD", "NVD-only is simpler but cannot supply all timely vendor applicability. Commercial APIs may save work but add cost, terms and dependency.", "Validate real source samples, revisions and quota/terms in D01\u2013D05. Fallback: a trusted stale snapshot and isolated adapter failures."], ["Vendor data", "Ubuntu OSV first; MSRC and Red Hat CSAF/VEX as scoped extensions", "Vendor data explains supported branches and backports. OVAL is a useful cross-check; scraping and CPE-only matching lose important semantics.", "Qualify one release/profile at a time; check source-package mapping, licensing and entitlement. Fallback: reviewed manual assertion or unknown."], ["Asset and vulnerability identity", "Internal IDs + typed alias/upstream/related links; CPE/purl where useful", "CVE-only keys exclude non-CVE records; purl alone cannot identify every appliance. SBOM is evidence, not proof of runtime exposure.", "Exercise collisions, revision boundaries and VEX scope. Keep ambiguous identities separate for review."], ["Applicability", "Deterministic vendor-aware tri-state rules", "Fuzzy or LLM matching can propose candidates but is insufficient as a security verdict. Vendor-native comparisons handle backports and ecosystem versions.", "D09/C08/D15 verify gold cases and evidence traces. Missing semantics or configuration stays unknown."], ["Prioritization", "Explained policy bands using distinct signals and context", "CVSS is severity; EPSS is a dated forecast; KEV is an exploitation signal. Weighted/learned alternatives need calibration or local labels.", "Review conflicting and missing-signal cases in D12. Internal deadlines are policy, not copied regulatory obligations."], ["Discovery and inventory", "Bounded independently installed Nmap + authenticated inventory", "Native SSH fits the first Ubuntu slice; compare osquery/Wazuh for Windows. Greenbone is an optional heavier comparison, not first-term dependency.", "Measure scope, field coverage, footprint and privileges. Nmap/Npcap distribution terms and fragile devices require explicit limits; fallback to reviewed imports."], ["Patch execution", "Build orchestration; reuse native update engines", "An allowlisted Ansible adapter is the first candidate. Direct native execution is a fallback with more parsing/reboot responsibility; do not build a package manager.", "Prove an approved Ubuntu canary, interruption and recovery. Windows has a separate gate; check-mode and exit code zero do not prove compatibility or closure."], ["Backend boundary", "Modular Python codebase with isolated privileged execution", "Microservices add coordination and operations before a measured scaling need. Workers can share domain code while the runner retains a separate trust boundary.", "Typed contracts and denied out-of-scope actions must pass. Split further only for measured scaling or required trust boundaries."], ["Backend framework", "FastAPI conditional default; Django is a strong fallback", "OpenAPI/Python suit the integration boundary; Django brings auth/admin capabilities. NestJS fits strong TypeScript teams but adds a Python boundary here.", "P01 measures real team skills and a working endpoint/migration. Preserve contracts if learning or auth integration favors the fallback."], ["Product frontend", "React + TypeScript + Vite candidate", "A private dashboard needs stateful data flows more than SEO. Next.js may fit established team skill or future server-rendered requirements.", "Validate keyboard access and real pending/error/unknown states. Select maintained routing/data packages during the spike."], ["Persistence and search", "PostgreSQL relational core + JSONB; conditional pgvector", "MySQL JSON is valid if team capability favors it. A dedicated vector service adds synchronization/security/backup overhead until scale justifies it.", "Test integrity, filtered retrieval recall and restore. Start exact/lexical; add vector indexes only after evidence."], ["Durable jobs", "PostgreSQL job ledger/outbox; test Celery + RabbitMQ", "Redis/RQ and DB-only dispatch have real tradeoffs; broker acknowledgements do not produce exactly-once side effects.", "Crash/restart/duplicate/reconcile tests and resource measurements decide the transport. Fallback: bounded durable serial dispatch, not request-memory background work."], ["Identity and permissions", "Revocable server-side sessions and object-level authorization", "JWT is not an authorization model. Keycloak/OIDC adds operations but may be preferable for SSO or failed application-auth gates.", "Test CSRF, revocation, role/object denial and scoped runner credentials. Select a maintained auth component before implementation."], ["Infrastructure and evidence", "Linux Compose profiles + private filesystem evidence initially", "Kubernetes and multi-host object storage are later measured decisions. Existing laptops and budget do not imply recurring cloud capacity.", "Measure real hardware and restore DB+evidence consistently. Avoid a new legacy MinIO dependency; separate heavy services or use the minimal offline profile if needed."], ["Classification", "TF-IDF OneVsRest baselines with reviewed multilabel targets", "Frozen embeddings or a small encoder may help, but require fair splits, good labels and a measured improvement. Predicted severity never replaces provider CVSS.", "A01\u2013A05 require leakage checks, per-label errors and reproducible metrics. Keep the simpler baseline when a stronger model is unjustified."], ["Retrieval", "Exact IDs + lexical search + measured multilingual dense retrieval", "E5-small, BGE-M3 and economical comparators have different resource/token limits. Vector-only search loses exact facts; reranking adds cost.", "A06\u2013A08 compare relevance with authorization filters and actual latency/RAM. Preserve version-table context and stale revision handling."], ["Customized LLM", "Domain tools/retrieval/schema first; model chosen by a hardware/domain spike", "Researched Qwen and Gemma candidates have different runtime and terms. Hosted models need current cost/privacy review; no automatic retraining for every CVE.", "A09 measures the same reviewed questions, model/runtime revisions and quantization. Cited deterministic cards remain the fallback."], ["Assistant authority", "Typed read-only tools; draft separated from approval/execution", "Unrestricted agents increase attack surface; prompts, valid JSON and RAG do not guarantee truth or prevent injection.", "A10\u2013A12/P11 test authorization, malicious documents, false citations and stale plans. Disable AI without disabling core assessment."], ["SIEM and operations", "Outbox \u2192 JSON lines \u2192 Wazuh collection, decoder and rules", "A management REST endpoint is not assumed to ingest arbitrary events. Begin with required health counters; add tracing infrastructure when measured need justifies it.", "Prove the same event ID across source, dispatch and external alert; test replay and rotation. Export-only fallback is disclosed as such."], ["Differentiation", "Test change-aware decisions, targeted evidence and constrained fixes", "Chatbots, approvals and patch integrations alone are not novelty; current Tenable documentation already describes those capabilities.", "Use transparent baselines and controlled ablations. Claim only measured benefit in the declared scope, including negative findings."]];
function inline(s){let x=esc(s);x=x.replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,(_,a,u)=>`<a href="${u}" target="_blank" rel="noopener noreferrer">${a}</a>`).replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');x=x.replace(/\[(DS\d+|AI\d+|CY-S\d+|SRC-P\d+|G-S\d+|MR\d+|HT\d+)\]/g,(m,id)=>sources[id]?`<a href="${esc(sources[id].url)}" target="_blank" rel="noopener noreferrer">[${id}]</a>`:m);return x;}
function markdown(md){const ls=md.split('\n');let out='',code=false,buf=[],listType='';const close=()=>{if(listType){out+=`</${listType}>`;listType='';}};for(let i=0;i<ls.length;i++){let l=ls[i];if(l.startsWith('```')){close();if(code){out+='<pre><code>'+esc(buf.join('\n'))+'</code></pre>';buf=[];}code=!code;continue;}if(code){buf.push(l);continue;}if(l.trim().startsWith('|')&&i+1<ls.length&&/^\|[\s:|\-]+\|\s*$/.test(ls[i+1])){close();let cells=x=>x.trim().replace(/^\||\|$/g,'').split('|').map(c=>c.trim());out+='<div class="table-wrap"><table><thead><tr>'+cells(l).map(c=>'<th>'+inline(c)+'</th>').join('')+'</tr></thead><tbody>';i+=2;while(i<ls.length&&ls[i].trim().startsWith('|')){out+='<tr>'+cells(ls[i]).map(c=>'<td>'+inline(c)+'</td>').join('')+'</tr>';i++;}i--;out+='</tbody></table></div>';continue;}let h=l.match(/^(#{1,4})\s+(.*)/);if(h){close();out+=`<h${h[1].length}>${inline(h[2])}</h${h[1].length}>`;continue;}let li=l.match(/^\s*(?:[-*]|\d+[.)])\s+(.+)/);if(li){let typ=/^\s*\d/.test(l)?'ol':'ul';if(listType!==typ){close();listType=typ;out+=`<${typ}>`;}out+='<li>'+inline(li[1])+'</li>';continue;}close();if(l.trim())out+='<p>'+inline(l)+'</p>';}close();return out;}

// Dependencies are static planning relationships. Existing browser notes are left untouched.
function statusBadge(t){return `<span class="label">${gateNames[t.gate]} · project stage</span>`;}
// Plan-edit provenance records content changes, not team execution.
let changeWindow=B.changeTracking.latest;
const releaseById=Object.fromEntries(B.changeTracking.releases.map(r=>[r.id,r]));
function visibleChanges(records=[]){return records.filter(r=>changeWindow==='all'||(changeWindow==='recent'?releaseById[r.release]?.date>='2026-10-29':r.release===changeWindow));}
function taskChanges(id){return visibleChanges(B.changeTracking.tasks[id]||[]);}
function changeKind(id){let rows=taskChanges(id);return rows.some(r=>r.kind==='New')?'New':rows.length?'Updated':'';}
function changeTag(meta,compact=false){if(!meta)return '';let release=releaseById[meta.release];return `<span class="change-tag ${meta.kind.toLowerCase()} ${compact?'item-change':''}" title="${esc((release?.label||'Plan update')+' · '+(release?.date||'')+' · '+(meta.summary||''))}">${esc(meta.kind)}${release?` <time datetime="${release.date}">${esc(release.date)}</time>`:''}</span>`;}
function taskChangeTag(t){let rows=taskChanges(t.id);if(!rows.length)return '';return changeTag(rows.find(r=>r.kind==='New')||rows[rows.length-1]);}
function entityChangeTag(group,id){let rows=visibleChanges(B.changeTracking.entities[group]?.[id]||[]);return rows.length?changeTag(rows.find(r=>r.kind==='New')||rows[rows.length-1]):'';}
function sectionChangeTag(id){let r=B.changeTracking.sections[id];return r&&visibleChanges([r]).length?changeTag(r):'';}
function fieldChange(t,key,value){let rows=taskChanges(t.id);for(let i=rows.length-1;i>=0;i--){let r=rows[i],f=r.fields[key];if(value!==undefined){if(f?.added?.some(x=>JSON.stringify(x)===JSON.stringify(value)))return {release:r.release,kind:'New'};if(r.kind==='New')return {release:r.release,kind:'New'};}else if(f||r.kind==='New')return {release:r.release,kind:r.kind==='New'?'New':f.kind};}return null;}
function fieldTag(t,key){return changeTag(fieldChange(t,key));}
function trackedList(t,key,ordered=false){return `<${ordered?'ol':'ul'}>${t[key].map(x=>`<li>${esc(x)} ${changeTag(fieldChange(t,key,x),true)}</li>`).join('')}</${ordered?'ol':'ul'}>`;}
function editValue(v){return typeof v==='object'?(v?.name?v.name+': '+v.contribution:JSON.stringify(v)):String(v??'Not previously specified');}
function changeHistory(t){let rows=taskChanges(t.id);if(!rows.length)return '<p>No recorded package edits in this change window.</p>';return rows.slice().reverse().map(r=>`<article class="edit-release">${changeTag(r)}<b>${esc(releaseById[r.release].label)}</b><p>${esc(r.summary)}</p>${r.kind==='New'?'<p>This package was added. Its research, build, tests and artifacts are listed in the guide below.</p>':Object.entries(r.fields).map(([key,f])=>`<details class="edit-field"><summary>${esc(f.label)} <span class="change-tag ${f.kind.toLowerCase()}">${f.kind}</span></summary><div>${f.added?`${f.added.length?'<h4>Added</h4>'+list(f.added.map(editValue)):''}${f.removed.length?'<h4>Removed / replaced</h4>'+list(f.removed.map(editValue)):''}${f.reordered?'<p>The sequence was reordered; no item was added or removed.</p>':''}`:`<h4>Before</h4><p>${esc(editValue(f.before))}</p><h4>Now</h4><p>${esc(editValue(f.after))}</p>`}</div></details>`).join('')}</article>`).join('');}
function changeWindowOptions(){return [['recent','Changes since 29 Oct'],[B.changeTracking.latest,'This update only'],...B.changeTracking.releases.filter(r=>r.id!==B.changeTracking.latest&&r.date>='2026-10-29').slice().reverse().map(r=>[r.id,r.label+' · '+r.date]),['all','Archived change history (includes earlier dates)']].map(([v,l])=>`<option value="${v}" ${changeWindow===v?'selected':''}>${esc(l)}</option>`).join('');}
function changeLegend(){return `<div class="change-legend"><span class="change-tag new">New</span> Added to the plan <span class="change-tag updated">Updated</span> Existing plan changed <a href="#revision/changes">What changed →</a><small>By default, New/Updated badges show only 29 October edits. Older edits remain in archived history. Delivery colors describe expected work, not completion. Open a guide to see the changed sections and individual added items.</small></div>`;}
function changeIndex(){let ui=B.changeTracking.releases.filter(r=>changeWindow==='all'||(changeWindow==='recent'?r.date>='2026-10-29':r.id===changeWindow)).flatMap(r=>(r.interfaces||[]).map(x=>({...x,release:r.id})));let changed=B.tasks.filter(t=>taskChanges(t.id).length);return `<div class="change-controls"><label>Compare changes<select id="history-window" aria-label="Change history window">${changeWindowOptions()}</select></label><span>${changed.filter(t=>changeKind(t.id)==='New').length} new packages · ${changed.filter(t=>changeKind(t.id)==='Updated').length} updated packages</span><a download href="plan-change-log.md">Download change log</a></div>${changeLegend()}${ui.length?`<div class="interface-changes">${ui.map(x=>`<article class="card">${changeTag(x)}<h3>${esc(x.title)}</h3><p>${esc(x.summary)}</p><a class="source-link" href="${esc(x.route)}">Open updated explanation →</a></article>`).join('')}</div>`:''}<div class="change-index">${changed.map(t=>`<details class="decision"><summary><span class="task-id">${t.id}</span><div><h3>${esc(t.title)}</h3>${taskChangeTag(t)}<small>${esc(t.owner)} · ${taskChanges(t.id).map(r=>Object.keys(r.fields).map(k=>B.changeTracking.fields[k]).join(', ')||'New package').join(' / ')}</small></div></summary><div class="body">${changeHistory(t)}<a href="#work/${t.id}">Open execution guide →</a></div></details>`).join('')||'<p>No execution package content changed in this window. See the interface/explanation changes above.</p>'}</div>`;}
function hostingView(){let h=B.hosting;return `${note(h.summary)}<div class="legend-row"><span class="label">Primary owner: ${h.owner}</span>${sectionChangeTag('hosting')}<span class="label amber">${esc(h.status)}</span></div><div class="executive-flow hosting-steps">${h.sequence.map(x=>`<a class="flow-step" href="#work/${x[2]}"><b>${x[0]}</b><strong>${esc(x[1])}</strong><small>${esc(x[3])}</small><span class="chip">${x[2]}</span></a>`).join('')}</div><div class="section-head"><h2>Where each component runs</h2></div>${table(['Component','Location','Access boundary','Gate / responsibility'],h.placement)}<details class="decision"><summary><h3>Which hosting option fits?</h3><span class="label amber">Needs Validation</span></summary><div class="body">${table(['Option','Why consider it','What must be checked','Position'],h.options)}${refs(h.sources)}</div></details><details class="decision"><summary><h3>What Omar must deliver</h3></summary><div class="body">${list(h.outputs)}${chips(['P01','P14','P17'])}<a download href="hosting-plan.md">Download hosting execution plan →</a></div></details>${note(h.gates.join(' '),true)}<a class="button" href="#work/P14">Open Omar’s complete hosting guide →</a>`;}
function overview(){return simpleStart();}
function revision(sub='scope'){const r=B.revision,tabs=[['scope','Scope'],['baseline','Scope baseline · Read'],['deployment','On-prem roadmap'],['hosting','Hosting · Omar'],['hams','Hams & handoff'],['value','Decision workflow'],['prioritization','AI prioritization · Hams'],['data','Data plan'],['trust','Tool trust'],['meeting','Meeting trace'],['changes','Change log']];if(!tabs.some(x=>x[0]===sub))sub='scope';let body='';if(sub==='scope')body=`<div class="grid two"><article class="card"><span class="label green">RECOMMENDED RELEASE</span><h2>Industrial-support IT</h2><p>${esc(r.thesis)}</p><p>One Ubuntu lab execution profile and one conditional FortiOS evidence profile. No assumed company systems or production access.</p><a href="#work/C01">Qualify the scope →</a></article><article class="card"><span class="label amber">VALIDATION GATES</span><h2>Make the claim fit the proof.</h2><p>Hardware, customer fit, vendor access, local model quality and exact supported versions remain open execution checks.</p><a href="#work/D18">Tool trust & rights →</a></article></div><div class="section-head"><h2>Capability is a matrix, not a promise.</h2></div>${table(['Profile','Collection','Assessment','Recommendation','Execution','Gate'],r.profiles)}<details class="decision"><summary><h3>Why this scope over the alternatives?</h3></summary><div class="body">${table(['Option','Strength','Constraint','Disposition'],r.alternatives)}${refs(['MR05','MR06','MR08'])}</div></details>${note('Existing extension guides remain available. Use Delivery scope in Execution Guides to distinguish current core, conditional profiles, experiments and deferred extensions.')}<div class="actions"><a class="button" href="#revision/baseline">Read the scope baseline →</a><a class="button soft" href="scope-baseline.md" download>Download scope-baseline.md</a><a class="button soft" href="#work">Explore the revised guides →</a></div>`;
if(sub==='baseline')body=`<div class="actions"><a class="button" href="scope-baseline.md" download>Download scope-baseline.md</a><a class="button soft" href="#revision/hams">Hams’s sequence and handoff →</a></div>${note('Read the shared scope before defining AI/UX tickets. Compare scope, data/context requirements and handoffs with the team. This baseline records the proposed scope and validation gates; it does not report completed work.')}<article class="research">${markdown(window.SCOPE_BASELINE)}</article>${note('Latest clarification: no fine-tuning in current execution; future capability review is in OQ01. The product is an integrated platform with conversational assistance.')}<a class="button soft" href="#open">Questions still to resolve →</a>`;
if(sub==='deployment')body=`${note('On-prem is a required long-term product direction. Prepare the enabling seams now, qualify capabilities in stages. An internal API is fully compatible with on-prem.')}<div class="deployment-path">${r.deploymentStages.map((x,i)=>`<details class="decision" ${i===0?'open':''}><summary><span class="stage-num">${i+1}</span><div><span class="label">${x.when}</span><h3>${esc(x.stage.slice(5))}</h3><small>${esc(x.owner)}</small></div></summary><div class="body"><h4>Build</h4><p>${esc(x.build)}</p><h4>Exit proof</h4><p>${esc(x.proof)}</p>${chips(x.packages)}</div></details>`).join('')}</div><details class="decision"><summary><h3>Separate the deployment choices</h3></summary><div class="body">${table(['Axis','Choices','Implementation boundary'],r.deploymentAxes)}</div></details><details class="decision"><summary><h3>What goes in the disconnected bundle?</h3></summary><div class="body">${list(['Pinned images and architecture manifest; image save/load does not include volumes.','Separate model/tokenizer/embedding artifacts, local evidence and consistent database backup.','Source snapshots with revision/as-of dates; optional approved package content if offline patching is claimed.','Migrations, configuration templates, license notices and operator runbook; secrets supplied separately.','Authenticated/trusted manifest, integrity checks and compatibility gate; hashes alone do not prove publisher authenticity.','Clean-host install with egress blocked, failed-update recovery and an explicit list of disabled capabilities.'])}${refs(['MR01','MR02','MR03','MR04'])}<a href="#work/P17">Full disconnected implementation guide →</a></div></details>${note('Cloud versus customer-hosted cost cannot be decided from an assumed free server or GPU. Measure hardware, power/hosting, operator time, backups, updates and support in P01/A09. Some customers accept cloud; requirements vary.',true)}`;
if(sub==='hams')body=`<div class="actions"><a class="button" href="#revision/baseline">Hams: read the shared scope baseline first →</a><a class="button soft" href="scope-baseline.md" download>Download scope-baseline.md</a></div><div class="grid two"><article class="card"><span class="label purple">HAMS LEADS</span><h2>AI + UI/UX research and design</h2><p>Taxonomy, data quality, retrieval and evaluation remain Hams-owned. UX01–UX03 add research, flows, prototype and usability. Optional models wait for evidence and capacity.</p>${chips(['UX01','UX02','UX03','A01','A04','A06','A07','A09'])}</article><article class="card"><span class="label">OMAR IMPLEMENTS</span><h2>Contract-driven platform</h2><p>Omar builds the frontend, API and integration. He can prepare the fixture shell while the design is being reviewed; UX02 gates completed P05 flows.</p>${chips(['P02','P05','P11','P14'])}</article></div>${table(['Sequence','Packages','Handoff','Boundary'],r.hamsPlan)}<div class="section-head"><h2>Before tickets move to ClickUp</h2></div>${list(r.handoffChecklist,true)}<div class="actions"><a class="button" href="clickup-handoff.csv" download>Download prepared ticket baseline</a><a class="button soft" href="scope-baseline.md" download>Scope + handoff contract</a><a class="button soft" href="#work/owner-Hams">Hams: owned and supporting work →</a></div>${note('The CSV is a prepared import file, not synchronized ClickUp state. It includes full guide links and scope versions. Reconcile actual artifacts first; no task is claimed complete or sent to ClickUp.')}`;
if(sub==='prioritization')body=prioritizationGuide();
if(sub==='value')body=`<div class="section-head"><h2>From volume to the next defensible action</h2></div><div class="executive-flow">${r.assistantFlow.map(x=>`<div class="flow-step"><b>${x[0]}</b><strong>${x[1]}</strong><small>${esc(x[2])}</small></div>`).join('')}</div>${table(['Decision','Rule'],r.ranking)}<div class="grid two"><article class="card"><h3>Rules guard security boundaries</h3><p>Applicability, hard policy constraints, permissions and approval remain deterministic. A17 compares AI/hybrid ordering of eligible actions against the D12 transparent baseline; no candidate is promoted without evaluation.</p>${chips(['D09','D12','C10','P08'])}</article><article class="card"><h3>AI explains evidence</h3><p>Retrieve governed documents, read current authorized facts, explain priorities and draft constrained recommendations. Abstain when evidence is missing.</p>${chips(['A06','A10','A11','A12'])}</article></div>${note('BERT/SecBERT is not a drop-in generative chatbot. RAG is not the canonical database. Some hosted APIs permit tuning, but tuning does not solve live context or freshness. LangGraph is an optional implementation experiment, not a required rewrite.')}${refs(['MR09','MR10','MR11'])}`;
if(sub==='data')body=`${table(['Need','Source','What this proves / limitation','Work packages'],r.dataMatrix)}${note('No verified public dataset is assumed to contain this organization’s current assets, policies, maintenance constraints and repair history. Obtain consented data if available; otherwise state exactly which context is a synthetic fixture.',true)}<details class="decision"><summary><h3>Data acceptance before evaluation</h3></summary><div class="body">${list(['Manifest records origin, license/rights, source revision, hash, timestamp and split.','Group revisions and near-duplicate advisories before splitting.','Use reviewed labels independent of the evaluated rule/model where possible.','Report real-record, real-lab and synthetic-scenario results with separate denominators.','Never score generated labels as independent ground truth or display synthetic data as a real customer incident.'])}${chips(['A02','A03','D15','D18'])}</div></details>`;
if(sub==='trust')body=`<article class="card"><span class="label green">SHAMS / D18</span><h2>Trust must be inspectable.</h2><p>Maintain one register for tools, models, data sources and distribution artifacts. Technical availability, permitted use and commercial redistribution are separate questions.</p>${chips(['D18','D01','P11','P14'])}</article>${table(['Register field','Required answer'],[['Identity','Exact artifact/version, publisher, source URL and reviewer'],['Rights','Internal use, commercial service, redistribution, derived content and attribution separately'],['Data boundary','What leaves the host: prompts, inventory, embeddings, logs, traces and telemetry'],['Operations','Updates, EOL, vulnerabilities, quotas, authentication and entitlement'],['Disposition','Allowed for declared use / restricted / unverified / excluded'],['Renewal trigger','Dependency, source terms, model or deployment capability changes']])}${note('No source or customer data resale is assumed. Base business hypotheses on the workflow/software value; sharing data requires verified source rights and an appropriate customer agreement.',true)}<details class="decision"><summary><h3>Operational fallbacks</h3></summary><div class="body">${list(['Model unavailable: cited deterministic findings and templates remain usable.','Source unavailable: preserve last trusted snapshot, label stale and alert; do not claim current freshness.','Fortinet access/semantics unqualified: keep the Ubuntu core and a disclosed reviewed import profile.','Unclear distribution rights: exclude or restrict the capability to verified permitted use.','Offline update unavailable: show snapshot age; internet freshness targets do not apply to a disconnected feed.'])}</div></details>`;
if(sub==='meeting')body=`${r.meeting.map(x=>`<details class="decision"><summary><span class="label">${x[1]}</span><h3>${esc(x[0])}</h3></summary><div class="body"><p>${esc(x[2])}</p><h4>Execution + owner</h4>${x[3].map(id=>`<p>${link(id)} ${esc(tasks[id].owner)} · ${esc(tasks[id].title)}</p>`).join('')}<h4>Evidence</h4>${x[4].length?refs(x[4]):'<p>Team requirement / project recommendation; no external statistical claim.</p>'}<p>Acceptance: open the linked package’s TEST section. Recommendations remain conditional until its proof gate passes.</p></div></details>`).join('')}`;
if(sub==='changes')body=changeIndex();
if(sub==='hosting')body=hostingView();
return heading('SCOPE / '+r.version,'A focused release. A foundation for the product.','This revision applies the meeting notes and the latest on-prem correction. It is an executable planning baseline, not a report that the product or experiments are complete.')+`<div class="toc revision-tabs">${tabs.map(([id,label])=>`<a href="#revision/${id}" class="${id===sub?'selected':''}" ${id===sub?'aria-current="page"':''}>${label} ${sectionChangeTag(id)}</a>`).join('')}</div><div class="revision-content">${body}</div><div class="actions section-head"><a class="source-link" href="#evidence/revision">Full revision evidence and alternatives →</a><a class="source-link" href="#revision/${tabs[(tabs.findIndex(x=>x[0]===sub)+1)%tabs.length][0]}">Next: ${tabs[(tabs.findIndex(x=>x[0]===sub)+1)%tabs.length][1]} →</a></div>`;}
function system(id='match'){let c=C[id]||C.match,before=edges.filter(x=>x[1]===c.id).map(x=>C[x[0]]),after=edges.filter(x=>x[0]===c.id).map(x=>C[x[1]]);return heading('02 / SYSTEM ARCHITECTURE','See the system. Follow the evidence.','Select a component to highlight its inputs and consumers, then open its owner, packages and decisions.')+`<div class="map-controls"><span class="label green">Retained design</span><span class="tagline">Arrows: evidence/data flow. Dashed AI link: a draft for human review, never direct execution.</span><button class="button soft" id="tour">Play guided tour</button><button class="button soft" id="stop-tour">Stop</button></div><div class="map-layout"><div class="system-canvas">${systemSVG(c.id)}<div class="platform-bar">PLATFORM · RBAC · PostgreSQL · durable jobs · audit · source health</div></div><aside class="node-inspector" aria-live="polite"><span class="label">${names[c.stream]}</span><h2>${c.label}</h2><p class="owner-line">${c.owner}</p><dl><dt>Inputs</dt><dd>${esc(c.input)}</dd><dt>Outputs</dt><dd>${esc(c.output)}</dd><dt>Why</dt><dd>${esc(c.why)}</dd></dl><h4>Execution packages</h4>${chips(c.ids)}<h4>Before / after</h4><div class="chips">${before.map(x=>`<a class="chip" href="#system/${x.id}">Before: ${x.label}</a>`).join('')}${after.map(x=>`<a class="chip" href="#system/${x.id}">After: ${x.label}</a>`).join('')}</div><h4>Decisions</h4><div class="chips">${c.adr.map(x=>`<a class="chip" href="#decisions/${x}">${x}</a>`).join('')}</div></aside></div><details class="decision"><summary><b>Text navigation for every component</b></summary><div class="body"><div class="chips">${components.map(x=>`<a class="chip" href="#system/${x.id}">${x.label}</a>`).join('')}</div></div></details><div class="sim"><h3>Change the evidence. See the next action.</h3><p class="tagline">Static teaching scenarios, not real CVEs or live scans.</p><div class="buttons">${['New vulnerability','Old version, backported fix','Missing evidence','Lost contact during patch'].map((x,i)=>`<button data-case="${i}" aria-pressed="${i===0}">${x}</button>`).join('')}</div><div id="sim-result" class="sim-result" aria-live="polite"></div></div><a class="button soft" href="#evidence/integration" style="margin-top:20px">API contracts, entities and state machines →</a>`;}
function executionSection(label,sub,content,open=false){return `<details class="execution-section" ${open?'open':''}><summary><b>${label}</b><span>${sub}</span></summary><div class="execution-content">${content}</div></details>`;}
function taskCard(t,open=false){return `<details class="task" id="task-${t.id}" ${open?'open':''}><summary><span class="task-id">${t.id}</span><div class="task-title">${esc(t.title)} ${taskChangeTag(t)}<small>${esc(t.owner)} · ${names[t.stream]}</small>${scheduleTags(t)}${taskOutsideBrief(t)}</div><div class="summary-status">${statusBadge(t)}${t.criticalPath?'<span class="label">Core path</span>':''}</div></summary><div class="task-body"><div class="breadcrumb">PROJECT → ${names[t.stream]} → ${t.gate} → ${esc(t.component)} → ${t.id}</div>${workflowTaskLinks(t)}${taskSectionNav(t)}${simpleTaskGuide(t)}${taskChanges(t.id).length?executionSection('What changed','Exact plan edits, dates and previous values',changeHistory(t)):""}<div class="package-goal"><span class="kicker">GOAL ${fieldTag(t,'goal')}</span><h3>${esc(t.goal)}</h3><p><b>Why this matters:</b> ${esc(t.why)}</p><div class="first-action"><b>First action</b><span>${esc(t.firstAction)}</span></div></div><div class="task-status"><span class="label">Owner: ${esc(t.owner)}</span><span class="label">Support: ${esc(t.support.join(' · '))}</span><span class="label">${esc(t.releaseLayer)}</span>${t.workTypes.map(x=>`<span class="label">${x}</span>`).join('')}</div>${studyPackageNote(t)}${executionSection('Support & handoff '+fieldTag(t,'supportContributions'),'Who helps, when they join and what they deliver',supportTable(t))}${t.revisionNotes?.length?executionSection('Scope revision',B.revision.version,list(t.revisionNotes)+`<a class="source-link" href="#revision/changes">Change log and shared handoff →</a>`):''}<div class="dependency-strip"><div><b>Depends on ${fieldTag(t,'depends')}</b>${chips(t.depends)}</div><div><b>Unlocks</b>${chips(t.next)}</div><div><b>Parallel with</b>${chips(t.parallelWith)}</div></div><p class="start-state">${t.depends.length?'Planned prerequisites: '+esc(t.depends.join(', ')):'Foundation package — no planned prerequisite.'}</p>${t.conditionalGates.length?note('Conditional capability gates: '+t.conditionalGates.join(' '),true):''}<p class="tagline">Scope: ${esc(t.scopeVersion)} · ${esc(t.releaseLayer)}. This is a plan reference; no completion is recorded here.</p><p class="tagline">Parallel means no dependency path between the packages; each still needs its own prerequisites and team capacity. Critical path: <b>${t.criticalPath?'Yes':'No'}</b> — core dependency chain, not a duration-calculated CPM.</p>${taskInputSection(t)}<div id="task-research-${t.id}" class="task-section-anchor">${executionSection('🔎 RESEARCH '+fieldTag(t,'researchQuestions'),'Questions and the evidence already available',`<span class="label amber">RESEARCH REQUIRED: execution checks</span><p>${esc(t.researchBasis)}</p>${trackedList(t,'researchQuestions',true)}${assetResearchBrief(t)}<h4>Technical approach ${fieldTag(t,'technicalApproach')}</h4><span class="label ${t.decisionState==='Existing Design Decision'?'purple':'amber'}">${t.decisionState}</span><p>${esc(t.technicalApproach)}</p><h4>Source starting points</h4>${refs(t.researchRefs)}<p class="tagline">Use these retained sources first. Recheck only unresolved details or information that changed at implementation time.</p>`)}</div><div id="task-build-${t.id}" class="task-section-anchor">${executionSection('⚙️ BUILD '+fieldTag(t,'implementationSteps'),'Numbered actions and implementation details',`<h4>Required skills</h4>${list(t.skills)}<h4>Implementation steps ${fieldTag(t,'implementationSteps')}</h4>${trackedList(t,'implementationSteps',true)}${t.exampleFlow?`<h4>Example flow</h4><div class="sample-flow">${t.exampleFlow.map(row=>`<div>${row.map((x,i)=>`<span>${esc(x)}</span>${i<row.length-1?'<b aria-hidden="true">→</b>':''}`).join('')}</div>`).join('')}</div>`:''}`)}</div><div id="task-test-${t.id}" class="task-section-anchor">${executionSection('🧪 TEST '+fieldTag(t,'testing'),'How to prove it works and when it is DONE',`<h4>Testing sequence ${fieldTag(t,'testing')}</h4>${trackedList(t,'testing',true)}<h4>Acceptance criteria — all must be true</h4><ul class="acceptance-checks">${t.doneCriteria.map(x=>`<li>${esc(x)} ${changeTag(fieldChange(t,'doneCriteria',x),true)}</li>`).join('')}</ul><p class="tagline">Save the observed results, fixture/revision IDs and reviewer in the output notes. A fluent explanation or completed screen is not test evidence.</p>`)}</div><div id="task-output-${t.id}" class="task-section-anchor">${executionSection('📦 OUTPUT '+fieldTag(t,'deliverables'),'Concrete files, handoff format and output preview',taskOutputContents(t))}</div>${executionSection('Risks & fallback','Failure cases, alternatives and review links',`<h4>Risks / failure modes ${fieldTag(t,'executionRisks')}</h4>${trackedList(t,'executionRisks')}<h4>Fallback</h4><p>${esc(t.fallback)}</p><h4>Decisions and alternatives</h4><div class="chips">${t.decisions.map(id=>`<a class="chip" href="#decisions/${id}">${id}</a>`).join('')}<a class="chip" href="#evidence/${t.stream}">Retained research deep dive</a></div><h4>Dependency context</h4><a class="source-link" href="#delivery/${t.id}">Inspect this package's prerequisite graph →</a>`)}${taskGrowthSection(t)}<a class="source-link" href="#work/${t.id}">Permanent package link: ${t.id}</a></div></details>`;}
function work(sub=''){return simplifyExecutionMarkup(legacyWork(sub),sub);}
function legacyWork(sub=''){const roleRoute=sub.match(/^(owned|support)-(Shams|Amr|Mahrous|Hams|Omar)$/);if(roleRoute)filter={q:'',owner:roleRoute[2],role:roleRoute[1],stream:'',gate:'',type:'All',readiness:'',layer:'',weekStage:'',change:''};if(sub.startsWith('stream-'))filter={q:'',owner:'',stream:sub.slice(7),gate:'',type:'All',readiness:'',role:'both',layer:''};if(sub.startsWith('owner-'))filter={q:'',owner:sub.slice(6),stream:'',gate:'',type:'All',readiness:'',role:'both',layer:''};if(sub.startsWith('gate-'))filter={q:'',owner:'',stream:'',gate:sub.slice(5),type:'All',readiness:'',role:'both',layer:''};const focus=sub.match(/^week-(Shams|Amr|Mahrous|Hams|Omar)(?:-([15]))?$/);if(focus)filter={q:'',owner:focus[1],stream:'',gate:'',type:'All',readiness:'',role:'both',layer:'',weekStage:focus[2]==='1'?'first':focus[2]==='5'?'second':'week'};if(sub==='all')filter={q:'',owner:'',stream:'',gate:'',type:'All',readiness:'',role:'both',layer:'',weekStage:''};const selected=tasks[sub];if(selected)filter={q:'',owner:'',stream:'',gate:'',type:'All',readiness:'',role:'both',layer:''};return heading('EXECUTION / WORK PACKAGES','Execution workspace','Browse the complete plan, or focus on a person, workstream or prototype delivery. Owned work and supporting work stay separate.')+`<div class="execution-people" aria-label="Team task shortcuts"><a href="#work/all" class="${filter.owner?'':'selected'}">All team</a>${B.owners.map(o=>`<a href="#work/owner-${o.name}" class="${filter.owner===o.name?'selected':''}">${o.name}</a>`).join('')}</div><section class="advanced-filters" aria-labelledby="execution-filters-title"><div class="filter-heading"><h2 id="execution-filters-title">Search & filters</h2><button id="clear-filters" class="button soft">Reset filters</button></div><div class="filters primary-filters"><label class="search">Search packages<input id="task-search" type="search" placeholder="CVE, schema, patch, D01…" value="${esc(filter.q)}"></label><label>Prototype delivery<select id="week-stage-filter" aria-label="Delivery date">${[['','All tasks'],['week','Prototype week · all parts'],['ready','Expected ready · verify draft'],['first','1 November'],['second','5 November'],['later','Later / optional this week']].map(([v,l])=>`<option value="${v}" ${filter.weekStage===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Workstream<select id="stream-filter" aria-label="Workstream">${[['','All workstreams'],['cyber','Cybersecurity'],['data','Intelligence and matching'],['ai','AI'],['platform','Platform']].map(([v,l])=>`<option value="${v}" ${filter.stream===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Owner<select id="owner-filter" aria-label="Owner"><option value="">All owners</option>${B.owners.map(o=>`<option ${filter.owner===o.name?'selected':''}>${o.name}</option>`).join('')}</select></label><label>Responsibility<select id="role-filter" aria-label="Responsibility">${[['both','Owned + Supporting'],['owned','Owned only'],['support','Supporting only']].map(([v,l])=>`<option value="${v}" ${filter.role===v?'selected':''}>${l}</option>`).join('')}</select></label></div><div class="execution-types" role="group" aria-label="Filter by work type">${['All','Research','Build','Experiment','Integration','Testing'].map(x=>`<button data-type="${x}" aria-pressed="${(filter.type||'All')===x}">${x}</button>`).join('')}</div><div class="filters secondary-filters"><label>Delivery scope<select id="scope-filter" aria-label="Delivery scope"><option value="">All delivery layers</option>${[...new Set(B.tasks.map(t=>t.releaseLayer))].map(v=>`<option ${filter.layer===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label><label>Gate<select id="gate-filter" aria-label="Gate"><option value="">All gates</option>${Object.entries(gateNames).map(([v,l])=>`<option value="${v}" ${filter.gate===v?'selected':''}>${v} · ${l}</option>`).join('')}</select></label><label>Plan relationship<select id="readiness-filter" aria-label="Plan relationship">${[['','All relationships'],['foundation','No prerequisites'],['dependent','Has prerequisites'],['critical','Core dependency chain']].map(([v,l])=>`<option value="${v}" ${filter.readiness===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Compare changes<select id="change-window" aria-label="Change window">${changeWindowOptions()}</select></label><label>Show changes<select id="change-filter" aria-label="Plan change filter">${[['','All packages'],['changed','Changed only'],['New','New only'],['Updated','Updated only']].map(([v,l])=>`<option value="${v}" ${filter.change===v?'selected':''}>${l}</option>`).join('')}</select></label></div><p class="filter-note">Delivery labels show planned work; they do not mark completion. <a href="#revision/changes">Change history and older edits →</a></p></section><div id="work-scope" class="execution-scope" aria-live="polite"></div><div id="work-responsibilities"></div><div id="work-count" class="count" aria-live="polite"></div><div id="work-results" data-selected="${selected?selected.id:''}"></div>`;}
function matchingTasks(){return orderExecutionTasks(legacyMatchingTasks());}
function legacyMatchingTasks(){return B.tasks.filter(t=>(!filter.weekStage||filter.weekStage==='all'||(filter.weekStage==='week'?Object.values(packageSchedule(t)).some(Boolean):filter.weekStage==='ready'?packageSchedule(t).ready:filter.weekStage==='first'?packageSchedule(t).first:filter.weekStage==='second'?packageSchedule(t).second:!Object.values(packageSchedule(t)).some(Boolean)))&&(!filter.stream||(filter.stream==='cyber'?['data','cyber'].includes(t.stream):t.stream===filter.stream))&&(!filter.owner||(filter.role==='owned'?t.owner===filter.owner:filter.role==='support'?t.support.includes(filter.owner):t.owner===filter.owner||t.support.includes(filter.owner)))&&(!filter.layer||t.releaseLayer===filter.layer)&&(!filter.change||(filter.change==='changed'?taskChanges(t.id).length>0:changeKind(t.id)===filter.change))&&(!filter.gate||t.gate===filter.gate)&&(!filter.q||JSON.stringify(t).toLowerCase().includes(filter.q.toLowerCase()))&&(!filter.type||filter.type==='All'||t.workTypes.includes(filter.type))&&(!filter.readiness||(filter.readiness==='foundation'?!t.depends.length:filter.readiness==='dependent'?t.depends.length>0:filter.readiness==='critical'?t.criticalPath:filter.readiness==='noncritical'?!t.criticalPath:true)));}
function supportTable(t){return t.supportContributions.map(r=>`<article class="support-row"><b>${esc(r.name)}</b><p>${esc(r.contribution)}</p><dl><dt>When</dt><dd>${esc(r.when)}</dd><dt>Handoff</dt><dd><code>${esc(r.deliverable)}</code></dd><dt>Acceptance</dt><dd>${esc(r.acceptance)}</dd></dl></article>`).join('')||'<p>No additional supporting owner is assigned.</p>';}
function renderWork(){let found=matchingTasks(),owner=filter.owner;$$('.execution-people a').forEach(a=>a.setAttribute('class',(owner?a.getAttribute('href')==='#work/owner-'+owner:a.getAttribute('href')==='#work/all')?'selected':''));$('#work-count').textContent=`${found.length} of ${B.tasks.length} tasks · dependency order · planned work`;let selected=$('#work-results').dataset.selected;$('#work-scope').innerHTML=executionScope();$('#work-responsibilities').innerHTML=owner?responsibilityOverview(owner,found):'';const group=rows=>Object.keys(gateNames).map(g=>{let ts=rows.filter(t=>t.gate===g);return ts.length?`<div class="phase-heading">${gateNames[g]} <small>${g} · project stage</small></div>${ts.map(t=>taskCard(t,t.id===selected)).join('')}`:''}).join('');let html='';if(owner){let owned=found.filter(t=>t.owner===owner),support=found.filter(t=>t.owner!==owner&&t.support.includes(owner));if(filter.role!=='support')html+=`<section class="responsibility-group"><h2>${esc(owner)} / Owned Work <span class="label">${owned.length}</span></h2><p>Primary responsibility: produce the artifacts, coordinate reviews and prove acceptance.</p>${group(owned)||'<p>No owned packages match these filters.</p>'}</section>`;if(filter.role!=='owned')html+=`<section class="responsibility-group supporting"><h2>${esc(owner)} / Supporting Work <span class="label purple">${support.length}</span></h2><p>Open Support & handoff in each guide for your contribution, timing and output. The primary owner remains accountable.</p>${group(support)||'<p>No supporting packages match these filters.</p>'}</section>`;}else html=group(found);$('#work-results').innerHTML=found.length?html:'<div class="empty">No packages match. Clear a filter or try a shorter search.</div>';bindTaskDetails($('#work-results'));if(selected){let el=$('#task-'+selected);if(el)el.scrollIntoView({block:'start',behavior:'auto'});$('#work-results').dataset.selected='';}}
function dependencyPanel(id){let t=tasks[id]||tasks.D09;return `<div class="dependency-inspector"><div><h4>Planned prerequisites</h4>${chips(t.depends)}</div><div class="focus-task"><span>${t.id} · ${t.owner}</span><h3>${esc(t.title)}</h3><a href="#work/${t.id}">Understand this package →</a></div><div><h4>Uses its result</h4>${chips(t.next)}</div></div><p class="tagline">${t.depends.length?'Comes after: '+t.depends.join(', '):'No planned prerequisite'} · Parallel candidates: ${t.parallelWith.join(', ')||'none listed'} · Core dependency chain: ${t.criticalPath?'Yes':'No'}. These are planned relationships, not team completion or live blockers.</p>`;}
function delivery(sub=''){if(sub.startsWith('week'))return prototypeWeekView(sub);return heading('04 / DELIVERY CONTROL','Work in parallel. Integrate at clear gates.','Study the planned order and the relationship between owners. A swimlane cell opens the relevant guides; it does not report actual scheduling or delivery.')+`<div class="actions"><a class="button" href="#delivery/week">Prototype week · 1 & 5 November →</a></div><div class="swimlane-wrap"><div class="swimlane"><div class="lane-head">Owner / gate</div>${Object.keys(gateNames).map(g=>`<a class="lane-head" href="#work/gate-${g}">${g}<small>${gateNames[g]}</small></a>`).join('')}${B.owners.map(o=>`<a class="lane-person" href="#team/${o.name}">${o.name}<small>${B.ui.owners.find(x=>x[0]===o.name)[1]}</small></a>${Object.keys(gateNames).map(g=>{let ts=B.tasks.filter(t=>t.owner===o.name&&t.gate===g);return `<button class="lane-cell" data-owner="${o.name}" data-gate="${g}" ${ts.length?'':'disabled'}>${ts.length?`<b>${ts.length} packages</b><small>${ts.slice(0,3).map(t=>t.id).join(' · ')}${ts.length>3?'…':''}</small>`:'Review / support'}</button>`}).join('')}`).join('')}</div></div>${note('Cells show primary ownership, not estimated hours or completion. Review, security and evaluation continue across gates. Fixtures let platform, cyber and AI development proceed before every live adapter is ready.')}<div class="section-head"><h2>Inspect a package’s dependencies.</h2><select id="dependency-select" aria-label="Choose a package">${B.tasks.map(t=>`<option value="${t.id}" ${(tasks[sub]?sub:'D09')===t.id?'selected':''}>${t.id} · ${esc(t.title)}</option>`).join('')}</select></div><div id="dependency-panel">${dependencyPanel(sub)}</div><div class="section-head"><h2>Protect the core delivery chain.</h2></div><div class="critical-chain">${[['Scope/contracts','P02'],['Inventory + vendor data','C05'],['Correct applicability','D09'],['Plan + policy','C10'],['Pilot execution','C11'],['Independent verification','C13'],['Reproducible evidence','C16']].map((x,i)=>`<a href="#work/${x[1]}"><b>${i+1}</b><span>${x[0]}</span><small>${x[1]}</small></a>`).join('')}</div>${note(B.ui.critical,true)}<div class="section-head"><h2>Yearlong gates</h2><p>Official dates remain unconfirmed. Earlier targets are historical; the separate weekly calendar sets only two prototype-slice checkpoints.</p></div><div class="roadmap">${B.ui.milestones.map(m=>`<article class="milestone" id="gate-${m[0]}"><div class="gate-num">${m[0]}</div><div class="card"><div class="when">${esc(m[1])}</div><h3>${esc(m[2])}</h3><details><summary>Deliverables, acceptance and parallel work</summary><dl>${[['Deliver',m[3]],['Acceptance',m[4]],['Parallel',m[5]],['Do not start',m[6]]].map(([k,v])=>`<dt>${k}</dt><dd>${esc(v)}</dd>`).join('')}</dl></details><a class="source-link" href="#work/gate-${m[0]}">Open gate packages →</a></div></article>`).join('')}</div>`;}
function team(sub=''){return heading('TEAM / VECTOR FIVE','Understand the five engineering domains.','Hams leads AI and UI/UX design. Omar implements the platform. Amr owns vulnerability data and remediation execution; Shams owns asset contracts, discovery, inventory and independent asset verification; Mahrous owns applicability and policy.')+`<div class="team-network">${B.ui.owners.map(o=>`<a href="#team/${o[0]}" class="team-node"><span>${o[0][0]}</span><strong>${o[0]}</strong><small>${o[1]}</small></a>`).join('')}<div class="team-center">One scope version<br><b>${B.revision.version}</b></div></div>${note('Owned and supporting roles explain the engineering boundaries. Use the Study Desk to understand how they connect. This view explains planned ownership and supporting technical relationships; it records no team progress.')} ${B.ui.owners.map(o=>{let owned=B.tasks.filter(t=>t.owner===o[0]),support=B.tasks.filter(t=>t.owner!==o[0]&&t.support.includes(o[0]));return `<details class="person-card" id="person-${o[0]}" ${sub===o[0]?'open':''}><summary><div class="avatar">${o[0][0]}</div><div><h3>${o[0]}</h3><span class="role">${o[1]}</span></div><span class="label">${owned.length} owned · ${support.length} supporting</span><span class="expand-label">Open complete responsibility map</span></summary><div class="person-body">${responsibilityOverview(o[0])}<p class="why">${esc(o[2])}</p><dl>${[['Owns',o[3]],['Learn',o[4]],['First artifacts',o[5]],['Support',o[6]],['If waiting',o[7]],['Proof',o[8]]].map(([k,v])=>`<dt>${k}</dt><dd>${esc(v)}</dd>`).join('')}</dl><h3>Owned Work</h3><div class="compact-task-list">${owned.map(t=>`<a href="#work/${t.id}"><b>${t.id}</b><span>${esc(t.title)} ${taskChangeTag(t)}<small>${t.gate} · ${esc(t.releaseLayer)}</small></span></a>`).join('')}</div><h3>Supporting Work</h3><div class="compact-task-list">${support.map(t=>{let r=t.supportContributions.find(x=>x.name===o[0]);return `<details><summary><b>${t.id}</b><span>${esc(t.title)}<small>Owner: ${t.owner} · ${t.gate}</small></span></summary><div><p>${esc(r.contribution)}</p><p><b>When:</b> ${esc(r.when)}</p><p><b>Deliver:</b> <code>${esc(r.deliverable)}</code></p><p><b>Review:</b> ${esc(r.acceptance)}</p><a href="#work/${t.id}">Open full guide →</a></div></details>`}).join('')}</div><a class="button soft" href="#work/owner-${o[0]}">Explore owned + supporting guides →</a>${o[0]==='Omar'?'<a class="button soft" href="#revision/hosting">Hosting plan · Omar →</a>':''}</div></details>`}).join('')}<div class="actions"><a class="button soft" download href="faculty-brief.md">Team brief</a><a class="button soft" href="#revision/hams">Hams sequencing + shared handoff</a></div>`;}
function decisionCard(d,open=false){let i=B.decisions.indexOf(d),en=d.english||decisionCopy[i];return `<details class="decision" id="decision-${d.id}" ${open?'open':''}><summary><span class="task-id">${d.id}</span><div>${entityChangeTag('decisions',d.id)}<span class="label amber">${d.english?'Revision recommendation':'Retained recommendation'} · validate the stated gate</span><h3>${en[0]}</h3><p class="decision-choice">${en[1]}</p></div></summary><div class="body">${B.revision.decisionClarifications[d.id]?note('Current scope clarification: '+B.revision.decisionClarifications[d.id].join(', ')+'. The original record below is retained; the explicit scope revision and current package acceptance take precedence.',true):''}<div class="decision-split"><div><h4>Why / realistic alternatives</h4><p>${en[2]}</p></div><div><h4>Validation, limits and fallback</h4><p>${en[3]}</p></div></div><span class="label">Owner: ${esc(d.owner)}</span>${refs(d.sources)}<a class="source-link" href="#evidence/${d.chapter}">Full retained comparison, licensing and maintenance analysis →</a><details class="retained-record"><summary>Original decision record</summary>${table(['Field','Retained detail'],[['Choice',d.choice],['Why',d.why],['Alternatives',d.alternatives],['Gate',d.gate],['Risk',d.risk],['Fallback',d.fallback]])}</details></div></details>`;}
function decisions(id=''){return heading('06 / DECISION LOG','Every choice has a reason and a proof gate.','Original researched recommendations remain available. Four dated revision decisions clarify scope, on-prem delivery, organization-aware AI and the action queue; execution gates still require evidence.')+`<div class="legend-row"><span class="label green">VERIFIED FACT · linked evidence</span><span class="label">ASSUMPTION · unconfirmed context</span><span class="label purple">DESIGN DECISION · project recommendation</span><span class="label amber">NEEDS VALIDATION · experiment first</span></div><div class="decisions">${B.decisions.map(d=>decisionCard(d,d.id===id)).join('')}</div>`;}
const riskWord=x=>({'مرتفع':'High','متوسط':'Medium','حرج':'Critical'}[x]||x);
function riskDetails(r){let i=B.risks.indexOf(r),v=B.ui.riskSummaries[i];return `<details class="decision" id="risk-${r.id}"><summary><span class="task-id">${r.id}</span><div>${entityChangeTag('risks',r.id)}<span class="label amber">${riskWord(r.probability)} likelihood · ${riskWord(r.impact)} impact</span><h3>${B.ui.riskTitles[i]}</h3><small>${esc(r.owner)}</small></div></summary><div class="body"><dl>${[['Early signal',v[0]],['Prevention',v[1]],['Mitigation / fallback',v[2]]].map(([k,v])=>`<dt>${k}</dt><dd>${esc(v)}</dd>`).join('')}</dl><details class="retained-record"><summary>Original risk, response and contingency record</summary>${table(['Field','Retained detail'],[['Signal',r.signal],['Prevention',r.prevention],['Mitigation',r.mitigation],['Fallback',r.fallback]])}</details></div></details>`;}
function risks(){let cells=['مرتفع','متوسط'].map(prob=>['متوسط','مرتفع','حرج'].map(impact=>{let rr=B.risks.filter(r=>r.probability===prob&&r.impact===impact);return `<button class="risk-cell" data-prob="${prob}" data-impact="${impact}" aria-pressed="false"><b>${rr.length}</b><span>${riskWord(prob)} likelihood<br>${riskWord(impact)} impact</span><small>${rr.map(r=>r.id).join(' · ')||'No registered risks'}</small></button>`}).join('')).join('');return heading('07 / EARLY WARNING','Understand what could go wrong.','Study the possible failure, its early clue and the planned response. These are qualitative scenarios, not observed incidents or a live team risk review.')+`<div class="risk-matrix">${cells}</div><button class="button soft" id="all-risks">Show all risks</button><p id="risk-count" class="count" aria-live="polite">${B.risks.length} registered risks</p><div class="riskgrid" id="risk-results">${B.risks.map(riskDetails).join('')}</div><div class="section-head"><h2>Architecture challenge — retained corrections</h2></div><div class="grid two">${[['Cyber reviewer','Wrong product/version semantics can defeat good AI.','Vendor-native comparison, tri-state results, evidence freshness and reviewed fixtures.'],['AI reviewer','A chatbot alone is not a research contribution.','Independent labels, leakage-safe splits, transparent baselines and controlled ablations.'],['Software reviewer','The full stack may exceed the available machines.','Modular monolith, isolated runner, measured profiles and simpler tested fallbacks.'],['Supervisor','Scope and target percentages need clear denominators.','Supported profiles, requirement traceability, four discussion gates and reproducible evidence.'],['Real user','A patch list is not a safe repair workflow.','Constraints, approval, pilot, health checks, recovery and verified closure.'],['Forgotten cases','Source corrections, reboot-pending state and stale approvals can change an old result.','Versioned evidence, reassessment, invalidation and explicit reopened/unknown states.']].map(x=>`<details class="decision"><summary><h3>${x[0]}</h3></summary><div class="body"><p>${x[1]}</p><div class="note">${x[2]}</div></div></details>`).join('')}</div>`;}
function validation(){const expNames=['Confirm hardware and capacity','Compare collection methods','Exercise applicability edge cases','Recover durable jobs after failure','Benchmark retrieval quality','Select the LLM on real hardware','Prove patch pilot and recovery','Measure the proposed contribution','Verify security and usability'];const expTasks=[['P01'],['C05','C06'],['D09','D15'],['P07'],['A07','A08'],['A09'],['C11','C12','C13'],['A15'],['P15','A12','A13']];const reqs=[['24-hour CVE freshness',['D16'],'Keep publication-to-seen and seen-to-usable separate; disclose misses and missing upstream facts.'],['Controlled-lab detection',['D15','C16'],'Report TP/FN denominator, precision, unknowns and supported profile coverage.'],['Clear/actionable recommendations',['A13'],'Human actionability scoring is separate from factual support and critical-error counts.'],['AI classification',['A01','A04'],'Multilabel metrics, label review and source-backed versus inferred severity.'],['Actual SIEM integration',['P13','C15'],'Show the same event ID in outbox, decoder and correlated external alert.'],['Four-role access control',['P04'],'Negative API/object tests and separate patch-approval permissions.'],['Added patch lifecycle',['C10','C11','C13'],'Approved supported execution, interruption/recovery and independent verification.'],['Added retrieval/assistant',['A07','A10','P11'],'Current authorized evidence, valid citations and no arbitrary execution.'],['Measured differentiation',['A17','A15'],'Controlled baselines and limits; no untested superiority claim.']];return heading('08 / EXPERIMENTS & ACCEPTANCE','What proves that the work is complete?','Use the detailed test and acceptance checklists inside each linked execution guide. Existing proposal targets remain targets until measured.')+`<div class="grid">${B.experiments.map((e,i)=>`<details class="decision"><summary><span class="task-id">${e[0]}</span><h3>${expNames[i]}</h3></summary><div class="body"><h4>Execution guides</h4>${chips(expTasks[i])}<p>${esc(tasks[expTasks[i][0]].goal)}</p><h4>Start with these tests</h4>${list(tasks[expTasks[i][0]].testing)}<details class="retained-record"><summary>Original experiment protocol</summary><p dir="auto">${esc(e[2])}</p><p dir="auto">${esc(e[3])}</p><p dir="auto">${esc(e[4])}</p></details></div></details>`).join('')}</div><div class="section-head"><h2>Requirement → execution → evidence</h2></div><div class="grid two">${reqs.map((r,i)=>`<article class="card"><span class="label">${B.traceability[i][0]}</span><h3>${r[0]}</h3><p>${r[2]}</p>${chips(r[1])}</article>`).join('')}</div>${note('Unresolved choices are named experiments: hardware/capacity, exact backend/auth component, broker recovery, LLM serving and real Windows capability. They do not prevent contract-based parallel development.',true)}`;}
function evidence(ch=''){let chapters={data:'Intelligence and applicability',cyber:'Collection and patch management',ai:'AI: data to evaluation',platform:'Platform architecture',integration:'Contracts and state machines',revision:'Meeting revision and deployment evidence'};if(chapters[ch])return heading('09 / TECHNICAL DEEP DIVE',chapters[ch],'Retained research, alternatives, evidence and limitations. Execution-specific questions are also included inside every package.')+`${ch==='revision'?sectionChangeTag('meeting'):''}<div class="toc"><a href="#evidence">← Evidence index</a>${Object.entries(chapters).map(([k,v])=>`<a class="${k===ch?'selected':''}" href="#evidence/${k}">${v}</a>`).join('')}</div><article class="research">${markdown(B.research[ch])}</article><div class="section-head"><h2>Chapter sources</h2></div>${refs(B.sources.filter(s=>ch==='data'?s.id.startsWith('DS'):ch==='cyber'?s.id.startsWith('CY-'):ch==='ai'?s.id.startsWith('AI'):ch==='platform'?s.id.startsWith('SRC-P'):ch==='revision'?s.id.startsWith('MR'):s.id.startsWith('G-S')).map(s=>s.id))}`;return heading('09 / EVIDENCE LIBRARY','Keep the research. Make it actionable.','The completed research was reused. Open a chapter for deep context, or a package for specific research questions, build actions and tests.')+`<div class="grid">${Object.entries(chapters).map(([k,v],i)=>`<a class="stream-card" href="#evidence/${k}" style="--accent:${color[k]||'#245ea9'}"><span class="kicker">DEEP DIVE / 0${i+1}</span><h3>${v}</h3><p>Facts, alternatives, implementation, licensing, maintenance and evidence.</p><span>Open chapter →</span></a>`).join('')}</div><div class="section-head"><h2>Source register</h2><span class="tagline">${B.sources.length} references; original research dates are retained and meeting additions are dated separately.</span></div><div class="filters"><label class="search">Find a source or technology<input id="source-search" type="search" placeholder="Ubuntu, licensing, NVD, Qwen…"></label></div><div id="source-count" class="count" aria-live="polite"></div><div class="grid two" id="source-results"></div><div class="actions" style="margin-top:25px"><a class="button" download href="execution-guides.md">Download ${B.tasks.length} execution guides</a><a class="button soft" download href="master-blueprint.md">Complete blueprint</a><a class="button soft" download href="blueprint.json">Structured JSON</a><a class="button soft" download href="dependency-map.mmd">Dependency map</a></div>`;}
function renderSources(q=''){let ss=B.sources.filter(s=>JSON.stringify(s).toLowerCase().includes(q.toLowerCase()));$('#source-count').textContent=`${ss.length} source entries`;$('#source-results').innerHTML=ss.map(s=>`<article class="card source-card"><span class="label">${s.id}</span>${entityChangeTag('sources',s.id)}<h3><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a></h3><p>${esc(s.note||s.supports||s.type||s.kind||'Primary source')}</p><small>Reviewed: ${esc(s.accessed||s.verified_on||'2026-10-14')}</small></article>`).join('')||'<div class="empty">No sources match this search.</div>';}
function bind(view,sub){
 if(view==='workflow'||view==='outputs')bindWorkflow(view,sub);

 if(view==='study'&&sub==='terms'){studyTerms();$('#term-search').addEventListener('input',e=>studyTerms(e.target.value));}
 if(view==='revision'&&sub==='changes')$('#history-window').addEventListener('change',e=>{changeWindow=e.target.value;render('revision','changes');});
 if(view==='system'){$$('[data-case]').forEach(b=>b.addEventListener('click',()=>{$$('[data-case]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));showCase(+b.dataset.case);}));showCase(0);$('#tour').addEventListener('click',()=>{clearInterval(timer);let i=components.findIndex(c=>c.id===sub);timer=setInterval(()=>{i=(i+1)%components.length;location.hash='system/'+components[i].id;if(i===components.length-1){clearInterval(timer);timer=null;}},3500);});$('#stop-tour').addEventListener('click',()=>{clearInterval(timer);timer=null;});}
 if(view==='work'){renderWork();$$('a[href^="#work/"]').forEach(a=>a.addEventListener('click',e=>{if(a.getAttribute('href')===location.hash){e.preventDefault();render('work',location.hash.slice(6));}}));$('#week-stage-filter').addEventListener('change',e=>{filter.weekStage=e.target.value;filter.role=filter.owner&&['first','second'].includes(filter.weekStage)?'owned':'both';$('#role-filter').value=filter.role;renderWork();});$('#change-window')?.addEventListener('change',e=>{changeWindow=e.target.value;renderWork();});$('#task-search').addEventListener('input',e=>{filter.q=e.target.value;renderWork();});[['owner','owner-filter'],['stream','stream-filter'],['gate','gate-filter'],['readiness','readiness-filter'],['role','role-filter'],['layer','scope-filter'],['change','change-filter']].forEach(([k,id])=>$('#'+id)?.addEventListener('change',e=>{filter[k]=e.target.value;if(k==='owner'&&['first','second'].includes(filter.weekStage)){filter.role=filter.owner?'owned':'both';$('#role-filter').value=filter.role;}renderWork();}));$$('[data-type]').forEach(b=>b.addEventListener('click',()=>{filter.type=b.dataset.type;$$('[data-type]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));renderWork();}));$('#clear-filters').addEventListener('click',()=>{filter={q:'',owner:'',stream:'',gate:'',type:'All',readiness:'',role:'both',layer:''};render('work','');});}
 if(view==='delivery'&&!sub.startsWith('week')){$('#dependency-select').addEventListener('change',e=>$('#dependency-panel').innerHTML=dependencyPanel(e.target.value));$$('.lane-cell').forEach(b=>b.addEventListener('click',()=>{filter={q:'',owner:b.dataset.owner,gate:b.dataset.gate,stream:'',type:'All',readiness:'',role:'both',layer:''};location.hash='work';}));}
 if(view==='risks'){$$('.risk-cell').forEach(b=>b.addEventListener('click',()=>{$$('.risk-cell').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));let rs=B.risks.filter(r=>r.probability===b.dataset.prob&&r.impact===b.dataset.impact);$('#risk-results').innerHTML=rs.map(riskDetails).join('')||'<div class="empty">No registered risks in this cell.</div>';$('#risk-count').textContent=`${rs.length} risks in the selected cell`;}));$('#all-risks').addEventListener('click',()=>{$$('.risk-cell').forEach(x=>x.setAttribute('aria-pressed','false'));$('#risk-results').innerHTML=B.risks.map(riskDetails).join('');$('#risk-count').textContent=`${B.risks.length} registered risks`;});}
 if(view==='evidence'&&!B.research[sub]){renderSources();$('#source-search').addEventListener('input',e=>renderSources(e.target.value));}
}
function showCase(i){const cs=[['New advisory → reassess','Store the new record and source revision, then reassess relevant asset products. Sufficient evidence produces a supported verdict; incomplete evidence stays unknown.','Next: prioritize and review a plan. No automatic patch from advisory text.'],['Backport → native comparison','An old-looking banner may belong to a vendor-fixed package. Compare the full distro/package revision and release rather than only the upstream number.','Next: a source-backed not_affected result, or a precise missing-evidence request.'],['Unknown → targeted evidence','The OS is known but the build or source-package version is missing. Ask for that field rather than treating the asset as safe.','Next: collect authorized evidence and reassess.'],['Lost contact → reconcile','The connection was lost after installation started. Record outcome_unknown and inspect the target before repeating any mutation.','Next: reconnect → fresh inventory → health checks → safe resume or recovery.']];const c=cs[i];$('#sim-result').innerHTML=`<strong>${c[0]}</strong><p>${c[1]}</p><p><b>${c[2]}</b></p>`;}
function render(view,sub=''){if(!nav.some(n=>n[0]===view))view='overview';if(view!=='system'){clearInterval(timer);timer=null;}let same=route===view;route=view;$('#nav').innerHTML=sidebarNavigation(view,sub);const views={workflow,outputs,overview,study,open:openQuestions,revision,system,work,delivery,team,decisions,risks,validation,evidence,reference};$('#main').innerHTML=`<div class="breadcrumb"><a href="#overview">AegisLoop</a> / ${esc(nav.find(n=>n[0]===view)[1])}${sub?' / '+esc(routeDetailLabel(view,sub)):''}</div><div class="reveal">${studyPageHelp(view)}${views[view](sub)}</div>`;bind(view,sub);if(!same||view==='workflow'||view==='outputs'||view==='work'&&(sub==='all'||sub.startsWith('owner-')||sub.startsWith('week-'))||view==='revision'||view==='study'||view==='open'||(view==='delivery'&&sub.startsWith('week')))window.scrollTo({top:0,behavior:'auto'});const target=view==='work'?$('#task-'+sub):view==='decisions'?$('#decision-'+sub):view==='team'?$('#person-'+sub):view==='delivery'?$('#gate-'+sub):view==='open'?$('#question-'+sub):null;if(target){if('open'in target)target.open=true;target.scrollIntoView({block:'start',behavior:'auto'});}document.title=`${nav.find(n=>n[0]===view)[1]} — AegisLoop`;}
function routeHash(){let [v,s]=location.hash.slice(1).split('/');render(v||'overview',decodeURIComponent(s||''));}
window.addEventListener('hashchange',routeHash);$('#print').addEventListener('click',()=>{const closed=$$('#main details:not([open])');closed.forEach(d=>d.open=true);const restore=()=>{closed.forEach(d=>d.open=false);window.removeEventListener('afterprint',restore);};window.addEventListener('afterprint',restore);window.print();});routeHash();
